fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let n = nums.len();
    assert!(n >= 2); // Ensure the length of nums is at least 2

    // Create a hashmap to store the indices of the elements
    let mut indices = std::collections::HashMap::new();

    for i in 0..n {
        // Calculate the complement that we need to find
        let complement = target - nums[i];

        // Check if the complement exists in the hashmap
        if let Some(&j) = indices.get(&complement) {
            // Ensure i < j
            if i > j {
                return Some((j, i));
            } else {
                return Some((i, j));
            }
        }

        // Insert the current number and its index into the hashmap
        indices.insert(nums[i], i);
    }

    // If no valid pair is found, return None
    None
}